for db in ['data/guidebook.db','/tmp/claude-0/main.db']:
    c=sqlite3.connect(f'file:{db}?mode=ro',uri=True)
    rows=[r[0] for r in c.execute("select local_ref_id from source_slug_links where slug='accessible-circulation-geometry'")]
    pref={m.group(1) for m in (re.match(r"^([A-Za-z]*[-_]?)(\d+)$", t or "") for t in rows) if m and m.group(1)}
